import Foundation

private let nordVPNIconBase64 = ""

private let protonVPNIconBase64 = ""

func vpnIconPayload(for provider: String?) -> [String: Any] {
    let lower = (provider ?? "").lowercased()
    if lower.contains("nord") {
        return iconPayload(inlineBase64: nordVPNIconBase64)
    }
    if lower.contains("proton") {
        return iconPayload(inlineBase64: protonVPNIconBase64)
    }
    return [
        "type": "image",
        "id": "vpn-icon",
        "source": "sfSymbol",
        "systemImage": "network.badge.shield.half.filled",
        "tint": "blue"
    ] as [String: Any]
}

private func iconPayload(inlineBase64 base64: String) -> [String: Any] {
    [
        "type": "image",
        "id": "vpn-icon",
        "source": "inlineData",
        "mimeType": "image/png",
        "base64Data": base64
    ] as [String: Any]
}
